27	export const ONE_SECOND = 1000;
28	export const ONE_MINUTE = ONE_SECOND * 60;
29	export const ONE_HOUR = ONE_MINUTE * 60;
30	export const ONE_DAY = ONE_HOUR * 24;
31	export const ONE_YEAR = ONE_DAY * 365;
