33	export const defaultLeveledFormatter = {
34	    year: '{yyyy}',
35	    month: '{MMM}',
36	    day: '{d}',
37	    hour: '{HH}:{mm}',
38	    minute: '{HH}:{mm}',
39	    second: '{HH}:{mm}:{ss}',
40	    millisecond: '{HH}:{mm}:{ss} {SSS}',
41	    none: '{yyyy}-{MM}-{dd} {HH}:{mm}:{ss} {SSS}'
42	};
43	
44	const fullDayFormatter = '{yyyy}-{MM}-{dd}';
45	
46	export const fullLeveledFormatter = {
47	    year: '{yyyy}',
48	    month: '{yyyy}-{MM}',
49	    day: fullDayFormatter,
50	    hour: fullDayFormatter + ' ' + defaultLeveledFormatter.hour,
51	    minute: fullDayFormatter + ' ' + defaultLeveledFormatter.minute,
52	    second: fullDayFormatter + ' ' + defaultLeveledFormatter.second,
53	    millisecond: defaultLeveledFormatter.none
54	};
