56	export type PrimaryTimeUnit = 'millisecond' | 'second' | 'minute' | 'hour'
57	    | 'day' | 'month' | 'year';
58	export type TimeUnit = PrimaryTimeUnit | 'half-year' | 'quarter' | 'week'
59	    | 'half-week' | 'half-day' | 'quarter-day';
60	
61	export const primaryTimeUnits: PrimaryTimeUnit[] = [
62	    'year', 'month', 'day', 'hour', 'minute', 'second', 'millisecond'
63	];
64	export const timeUnits: TimeUnit[] = [
65	    'year', 'half-year', 'quarter', 'month', 'week', 'half-week', 'day',
66	    'half-day', 'quarter-day', 'hour', 'minute', 'second', 'millisecond'
67	];
68	
69	export function pad(str: string | number, len: number): string {
70	    str += '';
71	    return '0000'.substr(0, len - (str as string).length) + str;
72	}
73	
74	export function getPrimaryTimeUnit(timeUnit: TimeUnit): PrimaryTimeUnit {
75	    switch (timeUnit) {
76	        case 'half-year':
77	        case 'quarter':
78	            return 'month';
79	        case 'week':
80	        case 'half-week':
81	            return 'day';
82	        case 'half-day':
83	        case 'quarter-day':
84	            return 'hour';
85	        default:
86	            // year, minutes, second, milliseconds
87	            return timeUnit;
88	    }
89	}
90	
91	export function isPrimaryTimeUnit(timeUnit: TimeUnit): boolean {
92	    return timeUnit === getPrimaryTimeUnit(timeUnit);
93	}
94	
95	export function getDefaultFormatPrecisionOfInterval(timeUnit: PrimaryTimeUnit): PrimaryTimeUnit {
96	    switch (timeUnit) {
97	        case 'year':
98	        case 'month':
99	            return 'day';
100	        case 'millisecond':
101	            return 'millisecond';
102	        default:
103	            // Also for day, hour, minute, second
104	            return 'second';
105	    }
106	}
