108	export function format(
109	    // Note: The result based on `isUTC` are totally different, which can not be just simply
110	    // substituted by the result without `isUTC`. So we make the param `isUTC` mandatory.
111	    time: unknown, template: string, isUTC: boolean, lang?: string | Model<LocaleOption>
112	): string {
113	    const date = numberUtil.parseDate(time);
114	    const y = date[fullYearGetterName(isUTC)]();
115	    const M = date[monthGetterName(isUTC)]() + 1;
116	    const q = Math.floor((M - 1) / 3) + 1;
117	    const d = date[dateGetterName(isUTC)]();
118	    const e = date['get' + (isUTC ? 'UTC' : '') + 'Day' as 'getDay' | 'getUTCDay']();
119	    const H = date[hoursGetterName(isUTC)]();
120	    const h = (H - 1) % 12 + 1;
121	    const m = date[minutesGetterName(isUTC)]();
122	    const s = date[secondsGetterName(isUTC)]();
123	    const S = date[millisecondsGetterName(isUTC)]();
124	
125	
126	    const localeModel = lang instanceof Model ? lang
127	        : getLocaleModel(lang || SYSTEM_LANG) || getDefaultLocaleModel();
128	    const timeModel = localeModel.getModel('time');
129	    const month = timeModel.get('month');
130	    const monthAbbr = timeModel.get('monthAbbr');
131	    const dayOfWeek = timeModel.get('dayOfWeek');
132	    const dayOfWeekAbbr = timeModel.get('dayOfWeekAbbr');
133	
134	    return (template || '')
135	        .replace(/{yyyy}/g, y + '')
136	        .replace(/{yy}/g, pad(y % 100 + '', 2))
137	        .replace(/{Q}/g, q + '')
138	        .replace(/{MMMM}/g, month[M - 1])
139	        .replace(/{MMM}/g, monthAbbr[M - 1])
140	        .replace(/{MM}/g, pad(M, 2))
141	        .replace(/{M}/g, M + '')
142	        .replace(/{dd}/g, pad(d, 2))
143	        .replace(/{d}/g, d + '')
144	        .replace(/{eeee}/g, dayOfWeek[e])
145	        .replace(/{ee}/g, dayOfWeekAbbr[e])
146	        .replace(/{e}/g, e + '')
147	        .replace(/{HH}/g, pad(H, 2))
148	        .replace(/{H}/g, H + '')
149	        .replace(/{hh}/g, pad(h + '', 2))
150	        .replace(/{h}/g, h + '')
151	        .replace(/{mm}/g, pad(m, 2))
152	        .replace(/{m}/g, m + '')
153	        .replace(/{ss}/g, pad(s, 2))
154	        .replace(/{s}/g, s + '')
155	        .replace(/{SSS}/g, pad(S, 3))
156	        .replace(/{S}/g, S + '');
157	}
