159	export function leveledFormat(
160	    tick: TimeScaleTick,
161	    idx: number,
162	    formatter: TimeAxisLabelFormatterOption,
163	    lang: string | Model<LocaleOption>,
164	    isUTC: boolean
165	) {
166	    let template = null;
167	    if (zrUtil.isString(formatter)) {
168	        // Single formatter for all units at all levels
169	        template = formatter;
170	    }
171	    else if (zrUtil.isFunction(formatter)) {
172	        // Callback formatter
173	        template = formatter(tick.value, idx, {
174	            level: tick.level
175	        });
176	    }
177	    else {
178	        const defaults = zrUtil.extend({}, defaultLeveledFormatter);
179	        if (tick.level > 0) {
180	            for (let i = 0; i < primaryTimeUnits.length; ++i) {
181	                defaults[primaryTimeUnits[i]] = `{primary|${defaults[primaryTimeUnits[i]]}}`;
182	            }
183	        }
184	
185	        const mergedFormatter = (formatter
186	            ? (formatter.inherit === false
187	                ? formatter // Use formatter with bigger units
188	                : zrUtil.defaults(formatter, defaults)
189	            )
190	            : defaults) as any;
191	
192	        const unit = getUnitFromValue(tick.value, isUTC);
193	        if (mergedFormatter[unit]) {
194	            template = mergedFormatter[unit];
195	        }
196	        else if (mergedFormatter.inherit) {
197	            // Unit formatter is not defined and should inherit from bigger units
198	            const targetId = timeUnits.indexOf(unit);
199	            for (let i = targetId - 1; i >= 0; --i) {
200	                if (mergedFormatter[unit]) {
201	                    template = mergedFormatter[unit];
202	                    break;
203	                }
204	            }
205	            template = template || defaults.none;
206	        }
207	
208	        if (zrUtil.isArray(template)) {
209	            let levelId = tick.level == null
210	                ? 0
211	                : (tick.level >= 0 ? tick.level : template.length + tick.level);
212	            levelId = Math.min(levelId, template.length - 1);
213	            template = template[levelId];
214	        }
215	    }
216	
217	    return format(new Date(tick.value), template, isUTC, lang);
218	}
219	
220	export function getUnitFromValue(
221	    value: number | string | Date,
222	    isUTC: boolean
223	): PrimaryTimeUnit {
224	    const date = numberUtil.parseDate(value);
225	    const M = (date as any)[monthGetterName(isUTC)]() + 1;
226	    const d = (date as any)[dateGetterName(isUTC)]();
227	    const h = (date as any)[hoursGetterName(isUTC)]();
228	    const m = (date as any)[minutesGetterName(isUTC)]();
229	    const s = (date as any)[secondsGetterName(isUTC)]();
230	    const S = (date as any)[millisecondsGetterName(isUTC)]();
231	
232	    const isSecond = S === 0;
233	    const isMinute = isSecond && s === 0;
234	    const isHour = isMinute && m === 0;
235	    const isDay = isHour && h === 0;
236	    const isMonth = isDay && d === 1;
237	    const isYear = isMonth && M === 1;
238	
239	    if (isYear) {
240	        return 'year';
241	    }
242	    else if (isMonth) {
243	        return 'month';
244	    }
245	    else if (isDay) {
246	        return 'day';
247	    }
248	    else if (isHour) {
249	        return 'hour';
250	    }
251	    else if (isMinute) {
252	        return 'minute';
253	    }
254	    else if (isSecond) {
255	        return 'second';
256	    }
257	    else {
258	        return 'millisecond';
259	    }
260	}
261	
262	export function getUnitValue(
263	    value: number | Date,
264	    unit: TimeUnit,
265	    isUTC: boolean
266	) : number {
267	    const date = zrUtil.isNumber(value)
268	        ? numberUtil.parseDate(value)
269	        : value;
270	    unit = unit || getUnitFromValue(value, isUTC);
271	
272	    switch (unit) {
273	        case 'year':
274	            return date[fullYearGetterName(isUTC)]();
275	        case 'half-year':
276	            return date[monthGetterName(isUTC)]() >= 6 ? 1 : 0;
277	        case 'quarter':
278	            return Math.floor((date[monthGetterName(isUTC)]() + 1) / 4);
279	        case 'month':
280	            return date[monthGetterName(isUTC)]();
281	        case 'day':
282	            return date[dateGetterName(isUTC)]();
283	        case 'half-day':
284	            return date[hoursGetterName(isUTC)]() / 24;
285	        case 'hour':
286	            return date[hoursGetterName(isUTC)]();
287	        case 'minute':
288	            return date[minutesGetterName(isUTC)]();
289	        case 'second':
290	            return date[secondsGetterName(isUTC)]();
291	        case 'millisecond':
292	            return date[millisecondsGetterName(isUTC)]();
293	    }
294	}
